{"file_path": "C:/Users/盛龙科技/WorkBuddy/2026-08-18-09-08-28/miniprogram/utils/cloud.js", "content": "// 云函数调用封装（Promise 化），前端只与本小程序云环境通信，
// 密钥与翻译 API 调用全部在云函数内完成，符合微信安全规范。

const call = (name, data = {}) => {
  return new Promise((resolve, reject) => {
    wx.cloud.callFunction({
      name,
      data,
      success: (res) => resolve(res.result),
      fail: (err) => reject(err)
    });
  });
};

// 获取 openid（首次调用 login 云函数，结果缓存到 globalData）
const getOpenid = async () => {
  const app = getApp();
  if (app.globalData.openid) return app.globalData.openid;
  const res = await call('login');
  app.globalData.openid = res.openid;
  return res.openid;
};

module.exports = { call, getOpenid };
"}

