  const { text, source = 'auto', target = 'zh' } = event;
  if (!text) return { error: 'empty text' };

  const res = await client.TextTranslate({
    SourceText: text,
    Source: source,
    Target: target,
    ProjectId: 0
  });
  return { text: res.TargetText, source, target };
};
"}

