{"file_path": "C:/Users/盛龙科技/WorkBuddy/2026-08-18-09-08-28/miniprogram/cloudfunctions/asr/index.js", "content": "const cloud = require('wx-server-sdk');
const tencentcloud = require('tencentcloud-sdk-nodejs');

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });

// 腾讯云语音识别 ASR（一句话识别）
const AsrClient = tencentcloud.asr.v20190614.Client;
const client = new AsrClient({
  credential: {
    secretId: process.env.TENCENT_SECRET_ID,
    secretKey: process.env.TENCENT_SECRET_KEY
  },
  region: 'ap-guangzhou',
  profile: { httpProfile: { endpoint: 'asr.tencentcloudapi.com' } }
});

// event: { audioUrl(云存储fileID或URL), voiceFormat, lang }
// 注意：越南语识别需选用对应引擎模型，请参考腾讯云 ASR 文档
// 中文常用 '16k_zh'；越南语可尝试 '16k_vi'，以官方文档为准。
exports.main = async (event) => {
  const { audioUrl, voiceFormat = 'mp3', lang = 'zh' } = event;
  if (!audioUrl) return { error: 'empty audioUrl' };

  const EngineModelType = lang === 'vi' ? '16k_vi' : '16k_zh';

  const res = await client.SentenceRecognition({
    EngineModelType,
    ChannelNum: 1,
    ResTextFormat: 0,
    SourceType: 0,
    Url: audioUrl,
    VoiceFormat: voiceFormat
  });
  return { text: res.Result, lang };
};
"}

