{"file_path": "C:/Users/盛龙科技/WorkBuddy/2026-08-18-09-08-28/miniprogram/cloudfunctions/tts/index.js", "content": "const cloud = require('wx-server-sdk');
const tencentcloud = require('tencentcloud-sdk-nodejs');

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });

// 腾讯云语音合成 TTS
const TtsClient = tencentcloud.tts.v20190823.Client;
const client = new TtsClient({
  credential: {
    secretId: process.env.TENCENT_SECRET_ID,
    secretKey: process.env.TENCENT_SECRET_KEY
  },
  region: 'ap-guangzhou',
  profile: { httpProfile: { endpoint: 'tts.tencentcloudapi.com' } }
});

// event: { text, voiceType, codec }
// voiceType: 101016 为中文女声；越南语需选对应 VoiceType，见官方文档
exports.main = async (event) => {
  const { text, voiceType = 101016, codec = 'mp3' } = event;
  if (!text) return { error: 'empty text' };

  const res = await client.TextToVoice({
    Text: text,
    SessionId: Date.now().toString(),
    VoiceType: voiceType,
    Codec: codec
  });
  // 返回 base64 音频，前端写入临时文件后播放
  return { audioBase64: res.Audio, codec };
};
"}

