const { call, getOpenid } = require('../../utils/cloud');

Page({
  data: {
    recording: false,
    targetLang: 'vi',     // 译文语言：vi 越南语 / zh 中文
    recognized: '',
    translated: '',
    playing: false
  },

  onLoad() {
    getOpenid();
    this.recorder = wx.getRecorderManager();
    this.recorder.onStop((res) => this.onRecordStop(res));
    this.innerAudio = wx.createInnerAudioContext();
    this.innerAudio.onEnded(() => this.setData({ playing: false }));
  },

  // 切换录音
  toggleRecord() {
    if (this.data.recording) {
      this.recorder.stop();
      return;
    }
    wx.authorize({
      scope: 'scope.record',
      success: () => {
        this.setData({ recording: true, recognized: '', translated: '' });
        this.recorder.start({ duration: 60000, format: 'mp3', sampleRate: 16000 });
      },
      fail: () => wx.showToast({ title: '请先授权麦克风', icon: 'none' })
    });
  },

  // 录音结束 → 上传 → 识别 → 翻译
  async onRecordStop(res) {
    this.setData({ recording: false });
    wx.showLoading({ title: '识别中' });
    try {
      const upload = await wx.cloud.uploadFile({
        cloudPath: `audio/${Date.now()}.mp3`,
        filePath: res.tempFilePath
      });
      const asr = await call('asr', { audioUrl: upload.fileID, voiceFormat: 'mp3', lang: 'zh' });
      this.setData({ recognized: asr.text });

      const tr = await call('translate', {
        text: asr.text, source: 'zh', target: this.data.targetLang
      });
      this.setData({ translated: tr.text });
    } catch (e) {
      wx.showToast({ title: '处理失败，请重试', icon: 'none' });
    } finally {
      wx.hideLoading();
    }
  },

  // 播放译文（TTS 返回 base64，写入临时文件后播放）
  async play() {
    if (!this.data.translated) return;
    wx.showLoading({ title: '合成语音' });
    try {
      const tts = await call('tts', { text: this.data.translated, voiceType: 101016 });
      const fs = wx.getFileSystemManager();
      const path = `${wx.env.USER_DATA_PATH}/tts_${Date.now()}.mp3`;
      fs.writeFile({
        filePath: path, data: tts.audioBase64, encoding: 'base64',
        success: () => { this.innerAudio.src = path; this.innerAudio.play(); this.setData({ playing: true }); }
      });
    } catch (e) {
      wx.showToast({ title: '播放失败', icon: 'none' });
    } finally {
      wx.hideLoading();
    }
  },

  switchLang() {
    this.setData({ targetLang: this.data.targetLang === 'vi' ? 'zh' : 'vi' });
  }
});

