rawContent.text:
现在我了解了现有结构。让我补全：

1. **ocr 云函数** — `cloudfunctions/ocr/index.js` + `package.json`
   - 接收 fileID 或 base64，调用腾讯云 OCR（通用印刷体识别 GeneralBasicOCR / GeneralAccurateOCR）
   - 越南语菜单场景：腾讯云 OCR 支持 LanguageType 参数，可用 'auto' 或 'vie'（越南语）。实际上 GeneralBasicOCR 的 LanguageType 支持 'zh'/'zh_rare'/'eng'/'jap'/'kor'/'fre'/'spa'/'por'/'ger'/'ita'/'rus'/'dan'/'hol'/'swe'/'fin'/'nor'/'tha'/'vie' 等。越南语是 'vie'。
   - 需要从云存储下载文件（如果是 fileID），转为 base64，再调 OCR。或者直接传 URL。云存储 fileID 需要先获取临时下载 URL：cloud.getTempFileURL。然后把 URL 给 OCR（OCR 支持 Url 参数）。
   - 返回识别文字（拼接所有 detectedText 的 DetectedText）。

2. **pay 云函数** — `cloudfunctions/pay/index.js` + `package.json`
   - 使用云开发云支付 `cloud.cloudPay.unifiedOrder`
   - action: 'createOrder' → 创建会员订单，返回支付参数
   - action: 'queryOrder' → 查订单
   - action: 'onPayResult' → 支付结果回调（由 cloudPay 配置 functionName 指定）
   - 需要会员套餐配置（月卡/季卡/年卡）
   - 数据库 orders 集合

注意：现有 member.js 调用的是 `wx.cloud.callFunction({ name: 'createVipOrder' })`，但实际云函数名应该统一。我新建的云函数叫 `pay`，所以 member.js 里应该改成 `name: 'pay', data: { action: 'createOrder' }`。需要更新 member.js。

另外 photo.js 调用 `call('ocr', { fileID: upload.fileID })`，这跟我要写的 ocr 云函数入参一致（fileID）。很好，photo.js 不用大改，但 ocr 云函数要接收 fileID。

让我写 ocr 云函数：
- 入参 event: { fileID } 或 { imageBase64 }
- 如果是 fileID，用 cloud.getTempFileURL 拿临时URL，再用 OCR 的 Url 参数
- 调用通用印刷体 OCR，LanguageType='vie'（越南语）或 'auto'
- 拼接文字返回

腾讯云 OCR SDK：tencentcloud.ocr.v20181119.Client，方法 GeneralBasicOCR，参数 ImageBase64 或 ImageUrl，LanguageType。

需要安装 tencentcloud-sdk-nodejs（已经是其他云函数的依赖，OCR 同样需要）。

对于 member 的 pay 云函数，用 cloudPay。云支付 unifiedOrder 参数：
```
cloud.cloudPay.unifiedOrder({
  body: '会员套餐',
  outTradeNo: '订单号',
  spbillCreateIp: '127.0.0.1',
  subMchId: '商户号',  // 云支付里是 subMchId（服务商）或 mchId？实际上云开发云支付需要配置商户号。在云开发控制台"支付"里配置微信支付商户号后，调用 unifiedOrder 时不需要传 mchId，系统自动用配置的。但需要 functionName 指定回调。
  totalFee: 金额(分),
  envId: '云环境ID',
  functionName: 'pay',  // 接收支付结果的云函数名（即本函数）
  // 或 data?: 透传
  tradeType: 'JSAPI',
  openid: openid
})
```

实际上云开发云支付 unifiedOrder 的标准用法：
```
const res = await cloud.cloudPay.unifiedOrder({
  body: '会员',
  outTradeNo: orderId,
  spbillCreateIp: '127.0.0.1',
  subMchId: '商户号',     // 在云开发控制台配置微信支付后，这里填你的商户号（个体户申请的普通商户号）
  totalFee: 3000,          // 单位分
  envId: cloud.DYNAMIC_CURRENT_ENV,
  functionName: 'pay',     // 支付结果回调到此云函数，action=onPayResult
  tradeType: 'JSAPI',
  openid: openid
})
```
返回 res.payment 就是给 wx.requestPayment 的参数（含 nonceStr, package, paySign, signType, timeStamp）。前端直接 `wx.requestPayment(res.payment)`。

注意 subMchId 是云支付里需要的"商户号"。个体户申请微信支付后获得商户号（mch_id）。在云开发控制台"微信支付"里绑定后，调用时填 subMchId。但有些版本直接填 mchId。我会注释清楚：需要在云开发控制台绑定微信支付商户号，并把商户号填到环境变量 MERCHANT_ID，函数里读 process.env.MERCHANT_ID 作为 subMchId。

为了稳健，我把 MERCHANT_ID 放环境变量。

支付回调：cloudPay 在支付成功后调用 functionName 指定的云函数，event 里会有 `result` 字段（云支付回调结构）包含 appid, mchId, outTradeNo, resultCode, returnCode, sign, signType, timeStamp, totalFee, tradeType, transactionId, openid 等。我在 action='onPayResult' 里处理：更新 orders 集合状态为 paid，更新 users 会员到期时间。

订单存储：用 cloud.database()。需要集合 `orders` 和 `users`。

让我写一个完整但不过度复杂的 pay 云函数：

```js
const cloud = require('wx-server-sdk');
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
const db = cloud.database();
const _ = db.command;

// 会员套餐（价格单位：分）
const PLANS = {
  month: { id: 'month', name: '月卡会员', fee: 3000, days: 30 },
  quarter: { id: 'quarter', name: '季卡会员', fee: 8000, days: 90 },
  year: { id: 'year', name: '年卡会员', fee: 28000, days: 365 }
};

function genOrderNo() {
  return 'VIP' + Date.now() + Math.floor(Math.random() * 1000);
}

// 创建会员订单并返回支付参数
async function createOrder(openid, planId) {
  const plan = PLANS[planId] || PLANS.month;
  const orderNo = genOrderNo();
  await db.collection('orders').add({
    data: {
      orderNo, openid, planId: plan.id, planName: plan.name,
      fee: plan.fee, status: 'pending', createTime: db.serverDate()
    }
  });
  const res = await cloud.cloudPay.unifiedOrder({
    body: plan.name,
    outTradeNo: orderNo,
    spbillCreateIp: '127.0.0.1',
    subMchId: process.env.MERCHANT_ID,
    totalFee: plan.fee,
    envId: cloud.DYNAMIC_CURRENT_ENV,
    functionName: 'pay',   // 支付结果回调本函数 action=onPayResult
    tradeType: 'JSAPI',
    openid
  });
  return { orderNo, payment: res.payment };
}

// 查询订单
async function queryOrder(openid, orderNo) {
  const r = await db.collection('orders').where({ orderNo, openid }).get();
  return r.data[0] || null;
}

// 支付结果回调（云支付配置 functionName='pay' 时触发）
async function onPayResult(event) {
  const { result } = event;
  if (!result || result.resultCode !== 'SUCCESS') return { errcode: 0 };
  const orderNo = result.outTradeNo;
  const openid = result.openid;
  const order = (await db.collection('orders').where({ orderNo }).get()).data[0];
  if (!order || order.status === 'paid') return { errcode: 0 };
  const plan = PLANS[order.planId] || PLANS.month;
  const now = Date.now();
  const expire = now + plan.days * 86400000;
  await db.collection('orders').where({ orderNo }).update({ data: { status: 'paid', payTime: db.serverDate(), transactionId: result.transactionId } });
  // 用户会员状态
  const users = db.collection('users');
  const u = (await users.where({ openid }).get()).data[0];
  if (u) {
    const oldExpire = u.vipExpire && u.vipExpire > now ? u.vipExpire : now;
    await users.where({ openid }).update({ data: { isVip: true, vipExpire: Math.max(oldExpire, expire) } });
  } else {
    await users.add({ data: { openid, isVip: true, vipExpire: expire, createTime: db.serverDate() } });
  }
  return { errcode: 0 };
}

exports.main = async (event) => {
  const wxContext = cloud.getWXContext();
  const openid = wxContext.OPENID;
  const { action = 'createOrder', planId = 'month', orderNo } = event;
  try {
    if (action === 'createOrder') return { ok: true, ...(await createOrder(openid, planId)) };
    if (action === 'queryOrder') return { ok: true, order: await queryOrder(openid, orderNo) };
    if (action === 'onPayResult') return await onPayResult(event);
    return { ok: false, msg: 'unknown action' };
  } catch (e) {
    return { ok: false, msg: e.message };
  }
};
```

注意：云支付回调的 event 结构——当 functionName 指定的云函数被支付结果调用时，event 直接是支付结果对象（含 result 字段）。实际上云开发云支付的回调，event 里有 `result` 对象（微信支付结果），也可能 event 本身就是。我按官方样例：event.result 包含字段。稳妥起见我兼容 `event.result || event`。

另外 subMchId：在云开发控制台绑定微信支付后，调用 unifiedOrder 实际上**不需要**传 subMchId/mchId（系统从控制台配置读取）。但传了也行，有些文档要求填。为避免误导，我在注释说明：若已在云开发控制台"微信支付"绑定商户号，可省略 subMchId；若未绑定或想显式指定，填环境变量 MERCHANT_ID。函数里：`subMchId: process.env.MERCHANT_ID || undefined`。如果 undefined，云支付会用控制台绑定的。这样最稳。

我让 subMchId 可选。

现在 ocr 云函数：

```js
const cloud = require('wx-server-sdk');
const tencentcloud = require('tencentcloud-sdk-nodejs');

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });

const OcrClient = tencentcloud.ocr.v20181119.Client;
const client = new OcrClient({
  credential: { secretId: process.env.TENCENT_SECRET_ID, secretKey: process.env.TENCENT_SECRET_KEY },
  region: 'ap-guangzhou',
  profile: { httpProfile: { endpoint: 'ocr.tencentcloudapi.com' } }
});

// event: { fileID(云存储) } 或 { imageUrl } 或 { imageBase64 }
exports.main = async (event) => {
  let imageUrl, imageBase64;
  if (event.fileID) {
    const res = await cloud.getTempFileURL({ fileList: [event.fileID] });
    imageUrl = res.fileList[0].tempFileURL;
  } else if (event.imageUrl) {
    imageUrl = event.imageUrl;
  } else if (event.imageBase64) {
    imageBase64 = event.imageBase64;
  }
  if (!imageUrl && !imageBase64) return { error: 'no image provided' };

  const params = { LanguageType: 'vie' }; // 越南语优先；若图中含中文可改为 'auto'
  if (imageUrl) params.ImageUrl = imageUrl;
  if (imageBase64) params.ImageBase64 = imageBase64;

  const res = await client.GeneralBasicOCR(params);
  const text = (res.TextDetections || []).map(t => t.DetectedText).join('\n');
  return { text, count: (res.TextDetections || []).length };
};
```

OCR 的 LanguageType 'vie' 是通用印刷体支持的语言之一。如果不确定，用 'auto' 也行，但越南语菜单用 'vie' 更准。我默认 'vie'，并注释可改成 'auto' 或 'zh'。

注意：photo.js 里调用 `call('ocr', { fileID: upload.fileID })`，然后 `this.setData({ text: ocr.text })`。我的 ocr 返回 `{ text, count }`，一致。✓

现在更新 member.js 调用：原来 `wx.cloud.callFunction({ name: 'createVipOrder' })`，改成 `call('pay', { action: 'createOrder', planId: 'month' })`。返回结构 `{ ok:true, orderNo, payment }`，然后 `wx.requestPayment(payment)`。

