// 创建会员订单并返回支付参数
async function createOrder(openid, planId) {
  const plan = PLANS[planId] || PLANS.month;
  const orderNo = genOrderNo();
  await db.collection('orders').add({
    data: {
      orderNo, openid, planId: plan.id, planName: plan.name,
      fee: plan.fee, status: 'pending', createTime: db.serverDate()
    }
  });
  const res = await cloud.cloudPay.unifiedOrder({
    body: plan.name,
    outTradeNo: orderNo,
    spbillCreateIp: '127.0.0.1',
    subMchId: process.env.MERCHANT_ID,
    totalFee: plan.fee,
    envId: cloud.DYNAMIC_CURRENT_ENV,
    functionName: 'pay',   // 支付结果回调本函数 action=onPayResult
    tradeType: 'JSAPI',
    openid
  });
  return { orderNo, payment: res.payment };
}

// 查询订单
async function queryOrder(openid, orderNo) {
  const r = await db.collection('orders').where({ orderNo, openid }).get();
  return r.data[0] || null;
}

// 支付结果回调（云支付配置 functionName='pay' 时触发）
async function onPayResult(event) {
  const { result } = event;
  if (!result || result.resultCode !== 'SUCCESS') return { errcode: 0 };
  const orderNo = result.outTradeNo;
  const openid = result.openid;
  const order = (await db.collection('orders').where({ orderNo }).get()).data[0];
  if (!order || order.status === 'paid') return { errcode: 0 };
  const plan = PLANS[order.planId] || PLANS.month;
  const now = Date.now();
  const expire = now + plan.days * 86400000;
  await db.collection('orders').where({ orderNo }).update({ data: { status: 'paid', payTime: db.serverDate(), transactionId: result.transactionId } });
  // 用户会员状态
  const users = db.collection('users');
  const u = (await users.where({ openid }).get()).data[0];
  if (u) {
    const oldExpire = u.vipExpire && u.vipExpire > now ? u.vipExpire : now;
    await users.where({ openid }).update({ data: { isVip: true, vipExpire: Math.max(oldExpire, expire) } });
  } else {
    await users.add({ data: { openid, isVip: true, vipExpire: expire, createTime: db.serverDate() } });
  }
  return { errcode: 0 };
}

exports.main = async (event) => {
  const wxContext = cloud.getWXContext();
  const openid = wxContext.OPENID;
  const { action = 'createOrder', planId = 'month', orderNo } = event;
  try {
    if (action === 'createOrder') return { ok: true, ...(await createOrder(openid, planId)) };
    if (action === 'queryOrder') return { ok: true, order: await queryOrder(openid, orderNo) };
    if (action === 'onPayResult') return await onPayResult(event);
    return { ok: false, msg: 'unknown action' };
  } catch (e) {
    return { ok: false, msg: e.message };
  }
};
```

