### ocr 云函数

`cloudfunctions/ocr/index.js`:
```js
const cloud = require('wx-server-sdk');
const tencentcloud = require('tencentcloud-sdk-nodejs');

cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });

const OcrClient = tencentcloud.ocr.v20181119.Client;
const client = new OcrClient({
  credential: {
    secretId: process.env.TENCENT_SECRET_ID,
    secretKey: process.env.TENCENT_SECRET_KEY
  },
  region: 'ap-guangzhou',
  profile: { httpProfile: { endpoint: 'ocr.tencentcloudapi.com' } }
});

// event: { fileID(云存储fileID) } 或 { imageUrl } 或 { imageBase64 }
// 越南语菜单/招牌识别：LanguageType 用 'vie'；若图中混有中文可改 'auto'
exports.main = async (event) => {
  let imageUrl, imageBase64;

  if (event.fileID) {
    const res = await cloud.getTempFileURL({ fileList: [event.fileID] });
    const info = res.fileList && res.fileList[0];
    if (!info || !info.tempFileURL) return { error: 'file fetch failed' };
    imageUrl = info.tempFileURL;
  } else if (event.imageUrl) {
    imageUrl = event.imageUrl;
  } else if (event.imageBase64) {
    imageBase64 = event.imageBase64;
  }

  if (!imageUrl && !imageBase64) return { error: 'no image provided' };

  const params = { LanguageType: event.lang || 'vie' };
  if (imageUrl) params.ImageUrl = imageUrl;
  if (imageBase64) params.ImageBase64 = imageBase64;

  try {
    const res = await client.GeneralBasicOCR(params);
    const texts = (res.TextDetections || []).map(t => t.DetectedText);
    return { text: texts.join('\n'), count: texts.length };
  } catch (e) {
    return { error: e.message || 'ocr failed' };
  }
};
```

