### pay 云函数

`cloudfunctions/pay/index.js`:
```js
const cloud = require('wx-server-sdk');
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV });
const db = cloud.database();

// 会员套餐（totalFee 单位：分）
// 价格可在云开发控制台或环境变量覆盖；此处为默认示例
const PLANS = {
  month:   { id: 'month',   name: '月卡会员', fee: 3000,  days: 30 },
  quarter: { id: 'quarter', name: '季卡会员', fee: 8000,  days: 90 },
  year:    { id: 'year',    name: '年卡会员', fee: 28000, days: 365 }
};

const genOrderNo = () => 'VIP' + Date.now() + Math.floor(Math.random() * 1000);

// 1) 创建会员订单 + 微信支付统一下单，返回前端可直接调起支付的参数
async function createOrder(openid, planId) {
  const plan = PLANS[planId] || PLANS.month;
  const orderNo = genOrderNo();

  await db.collection('orders').add({
    data: {
      orderNo, openid,
      planId: plan.id, planName: plan.name,
      fee: plan.fee, status: 'pending',
      createTime: db.serverDate()
    }
  });

  const res = await cloud.cloudPay.unifiedOrder({
    body: plan.name,
    outTradeNo: orderNo,
    spbillCreateIp: '127.0.0.1',
    subMchId: process.env.MERCHANT_ID,     // 在云开发控制台“微信支付”绑定商户号后，此处可省略；显式指定则填环境变量
    totalFee: plan.fee,                    // 单位：分
    envId: cloud.DYNAMIC_CURRENT_ENV,
    functionName: 'pay',                   // 支付结果回调到本云函数 action=onPayResult
    tradeType: 'JSAPI',
    openid
  });

  return { orderNo, payment: res.payment };
}

// 2) 查询订单状态
async function queryOrder(openid, orderNo) {
  const r = await db.collection('orders').where({ orderNo, openid }).get();
  return r.data[0] || null;
}

// 3) 支付结果回调（云支付配置 functionName='pay' 时由微信触发）
// event 结构：{ result: { outTradeNo, openid, resultCode, transactionId, ... } }
async function onPayResult(event) {
  const result = event.result || event;
  if (!result || result.resultCode !== 'SUCCESS') return { errcode: 0 };

  const { outTradeNo, openid, transactionId } = result;
  const order = (await db.collection('orders').where({ orderNo: outTradeNo }).get()).data[0];
  if (!order || order.status === 'paid') return { errcode: 0 };

  const plan = PLANS[order.planId] || PLANS.month;
  const now = Date.now();
  const expire = now + plan.days * 86400000;

  await db.collection('orders').where({ orderNo: outTradeNo }).update({
    data: { status: 'paid', payTime: db.serverDate(), transactionId }
  });

  const users = db.collection('users');
  const u = (await users.where({ openid }).get()).data[0];
  if (u) {
    const base = (u.vipExpire && u.vipExpire > now) ? u.vipExpire : now;
    await users.where({ openid }).update({
      data: { isVip: true, vipExpire: Math.max(base, expire) }
    });
  } else {
    await users.add({ data: { openid, isVip: true, vipExpire: expire, createTime: db.serverDate() } });
  }
  return { errcode: 0 };
}

exports.main = async (event) => {
  const wxContext = cloud.getWXContext();
  const openid = wxContext.OPENID;
  const { action = 'createOrder', planId = 'month', orderNo } = event;

  try {
    if (action === 'createOrder') {
      const r = await createOrder(openid, planId);
      return { ok: true, ...r };
    }
    if (action === 'queryOrder') {
      return { ok: true, order: await queryOrder(openid, orderNo) };
    }
    if (action === 'onPayResult') {
      return await onPayResult(event);
    }
    return { ok: false, msg: 'unknown action' };
  } catch (e) {
    return { ok: false, msg: e.message };
  }
};
```

