    }
    if (action === 'queryOrder') {
      return { ok: true, order: await queryOrder(openid, orderNo) };
    }
    if (action === 'onPayResult') {
      return await onPayResult(event);
    }
    return { ok: false, msg: 'unknown action' };
  } catch (e) {
    return { ok: false, msg: e.message };
  }
};

{
  "name": "pay",
  "version": "1.0.0",
  "description": "会员订阅订单 + 微信支付（云开发云支付）",
  "main": "index.js",
  "dependencies": {
    "wx-server-sdk": "~2.6.3"
  }
}

const app = getApp();
const { call } = require('../../utils/cloud');

// 与云函数 pay 中的 PLANS 对应（仅用于前端展示价格）
const PLANS = [
  { id: 'month',   name: '月卡', price: '¥30',  desc: '30天无限翻译' },
  { id: 'quarter', name: '季卡', price: '¥80',  desc: '90天，省16%' },
  { id: 'year',    name: '年卡', price: '¥280', desc: '365天，最划算' }
];

Page({
  data: {
    isVip: false,
    freeQuota: 20,
    usedQuota: 0,
    remain: 20,
    plans: PLANS,
    selectedPlan: 'month'
  },

  onShow() {
    const remain = Math.max(0, app.globalData.freeQuota - app.globalData.usedQuota);
    this.setData({
      isVip: app.globalData.isVip,
      freeQuota: app.globalData.freeQuota,
      usedQuota: app.globalData.usedQuota,
      remain
    });
  },

  selectPlan(e) {
    this.setData({ selectedPlan: e.currentTarget.dataset.id });
  },

  // 订阅消息（会员到期/额度提醒），在用户主动操作后触发授权
  subscribe() {
    wx.requestSubscribeMessage({
      tmplIds: ['请填写订阅消息模板ID'],
      success: (res) => {
        if (res['请填写订阅消息模板ID'] === 'accept') {
          wx.showToast({ title: '已开启提醒', icon: 'success' });
        }
      }
    });
  },

  // 开通会员（微信支付）。云函数创建订单并返回支付参数。
  async buyVip() {
    if (this.data.isVip) return;
    wx.showLoading({ title: '发起支付' });
    try {
      const res = await call('pay', { action: 'createOrder', planId: this.data.selectedPlan });
      if (!res.ok) throw new Error(res.msg || '下单失败');

      // res.payment 由云支付统一下单返回，直接交给 wx.requestPayment
      await wx.requestPayment(res.payment);

      // 支付成功后同步会员状态到本地
      app.globalData.isVip = true;
      this.setData({ isVip: true });
      wx.showToast({ title: '会员开通成功', icon: 'success' });

      // 顺手请求订阅消息（会员到期/额度提醒），转化率最高
      this.subscribe();
    } catch (e) {
      const msg = (e && e.errMsg) ? e.errMsg : '';
      if (msg.indexOf('cancel') > -1) {
        wx.showToast({ title: '已取消支付', icon: 'none' });
      } else {
        wx.showToast({ title: '支付失败', icon: 'none' });
      }
    } finally {
      wx.hideLoading();
    }
  }
});

